```
s = empty ordered set
for each num in nums:
    insert num into s
    if size(s) > 3:
        remove the smallest element from s
if size(s) == 3:
    return smallest element in s
return largest element in s
```

code.cpp:
class Solution {
public:
    int thirdMax(vector<int>& nums) {
        set<int> s;
        for (int num : nums) {
            s.insert(num);
            if (s.size() > 3) {
                s.erase(s.begin());
            }
        }
        if (s.size() == 3) {
            return *s.begin();
        }
        return *s.rbegin();
    }
};
